const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let idx = 0;

const N = data[idx++];
const C = data[idx++];

const infectedByHuman = new Array(N + 1).fill(false);

for (let c = 0; c < C; c++) {
  const p = data[idx++];
  const i = data[idx++];

  let prev = p;
  for (let j = 0; j < i; j++) {
    const x = data[idx++];
    infectedByHuman[x] = true;
    prev = x;
  }
}

const answer = [];
for (let person = 1; person <= N; person++) {
  if (!infectedByHuman[person]) {
    answer.push(person);
  }
}

process.stdout.write(answer.join('\n'));
